package br.com.sistemacardapio.promocao;import java.math.BigDecimal;import java.time.Instant;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import br.com.sistemacardapio.catalogo.*;import br.com.sistemacardapio.tenant.TenantContext;
@Service public class PromocaoService{private final PromocaoRepository repo;private final ProdutoRepository produtos;private final TenantContext tenant;public PromocaoService(PromocaoRepository r,ProdutoRepository p,TenantContext t){repo=r;produtos=p;tenant=t;}@Transactional(readOnly=true)public List<Response>listar(){return repo.findAllByEmpresaIdOrderByInicioDesc(tenant.empresaIdObrigatoria()).stream().map(Response::from).toList();}@Transactional public Response criar(Request r){UUID e=tenant.empresaIdObrigatoria();Produto p=produtos.findByIdAndEmpresaId(r.produtoId(),e).orElseThrow(()->new IllegalStateException("Produto não encontrado"));validar(p,r);return Response.from(repo.save(new Promocao(p,r.precoPromocional(),r.tag(),r.inicio(),r.fim())));}@Transactional public Response atualizar(UUID id,Request r){UUID e=tenant.empresaIdObrigatoria();Promocao x=repo.findByIdAndEmpresaId(id,e).orElseThrow(()->new IllegalStateException("Promoção não encontrada"));Produto p=produtos.findByIdAndEmpresaId(r.produtoId(),e).orElseThrow();if(!p.getId().equals(x.getProduto().getId()))throw new IllegalStateException("Não é possível trocar o produto da promoção");validar(p,r);x.atualizar(r.precoPromocional(),r.tag(),r.inicio(),r.fim(),r.ativa());return Response.from(x);}private void validar(Produto p,Request r){if(r.precoPromocional().compareTo(p.getPreco())>=0)throw new IllegalStateException("Preço promocional deve ser menor que o normal");if(!r.fim().isAfter(r.inicio()))throw new IllegalStateException("Fim deve ser posterior ao início");}public record Request(@jakarta.validation.constraints.NotNull UUID produtoId,@jakarta.validation.constraints.NotNull @jakarta.validation.constraints.PositiveOrZero BigDecimal precoPromocional,@jakarta.validation.constraints.NotBlank String tag,@jakarta.validation.constraints.NotNull Instant inicio,@jakarta.validation.constraints.NotNull Instant fim,boolean ativa){}public record Response(UUID id,UUID produtoId,String produtoNome,BigDecimal precoPromocional,String tag,Instant inicio,Instant fim,boolean ativa){static Response from(Promocao p){return new Response(p.getId(),p.getProduto().getId(),p.getProduto().getNome(),p.getPrecoPromocional(),p.getTag(),p.getInicio(),p.getFim(),p.isAtiva());}}}
